<?php
namespace App\Core\Connectors\Drivers;use App\Core\Agents\Contracts\RiskLevel;use App\Core\Connectors\DTO\{ConnectorAction,ConnectorResult};use App\Models\ConnectorConnection;
final class ApifyConnector extends AbstractConnector {public function id():string{return 'apify';}public function label():string{return 'Apify Dynamic';}public function actions():array{return [new ConnectorAction('run_actor','Run any configured Apify Actor and return the run metadata.',RiskLevel::ExternalWrite,['type'=>'object','properties'=>['actor_id'=>['type'=>'string'],'input'=>['type'=>'object']],'required'=>['actor_id']]),new ConnectorAction('run_actor_sync','Run an Apify Actor synchronously and return dataset items.',RiskLevel::ExternalWrite,['type'=>'object','properties'=>['actor_id'=>['type'=>'string'],'input'=>['type'=>'object']],'required'=>['actor_id']]),new ConnectorAction('run_status','Read the status of an Apify Actor run.',RiskLevel::Read,['type'=>'object','properties'=>['run_id'=>['type'=>'string']],'required'=>['run_id']]),new ConnectorAction('dataset_items','Fetch dataset items by dataset ID.',RiskLevel::Read,['type'=>'object','properties'=>['dataset_id'=>['type'=>'string'],'limit'=>['type'=>'integer']],'required'=>['dataset_id']])];}public function configurationSchema():array{return ['credentials'=>['api_token'=>['type'=>'password','required'=>true]],'fields'=>[]];}public function test(ConnectorConnection $c):bool{try{return $this->client(['Authorization'=>'Bearer '.$this->bearer($c,'api_token')])->get('https://api.apify.com/v2/users/me')->successful();}catch(\Throwable){return false;}}public function execute(ConnectorConnection $c,string $action,array $a):ConnectorResult{$this->action($action);$client=$this->client(['Authorization'=>'Bearer '.$this->bearer($c,'api_token')]);return match($action){'run_actor'=>ConnectorResult::success($client->post('https://api.apify.com/v2/actors/'.rawurlencode((string)$a['actor_id']).'/runs',$a['input']??[])->throw()->json('data')),'run_actor_sync'=>ConnectorResult::success($client->timeout(300)->post('https://api.apify.com/v2/actors/'.rawurlencode((string)$a['actor_id']).'/run-sync-get-dataset-items',$a['input']??[])->throw()->json()),'run_status'=>ConnectorResult::success($client->get('https://api.apify.com/v2/actor-runs/'.rawurlencode((string)$a['run_id']))->throw()->json('data')),'dataset_items'=>ConnectorResult::success($client->get('https://api.apify.com/v2/datasets/'.rawurlencode((string)$a['dataset_id']).'/items',['clean'=>'true','limit'=>(int)($a['limit']??100)])->throw()->json()),default=>ConnectorResult::failure('Unsupported action')};}}
